const P = '__BQ_PROYECTO__', D = '__BQ_DATASET__', U = '__BQ_UBICACION__';
const t = n => '`' + P + '.' + D + '.' + n + '`';
const sql = [
  `CREATE SCHEMA IF NOT EXISTS \`${P}.${D}\` OPTIONS(location='${U}')`,
  `CREATE TABLE IF NOT EXISTS ${t('post_metrics_daily')} (snapshot_date DATE, post_id STRING, marca STRING, canal STRING, external_id STRING, published_at DATETIME, alcance INT64, interacciones INT64, reacciones INT64, comentarios INT64, compartidos INT64, guardados INT64, error STRING, loaded_at TIMESTAMP) PARTITION BY snapshot_date`,
  `CREATE TABLE IF NOT EXISTS ${t('social_account_daily')} (date DATE, marca STRING, canal STRING, account_id STRING, followers INT64, reach INT64, views INT64, profile_views INT64, engagements INT64, error STRING, loaded_at TIMESTAMP) PARTITION BY date`,
  `CREATE TABLE IF NOT EXISTS ${t('meta_ads_daily')} (date DATE, marca STRING, account_id STRING, campaign_id STRING, campaign_name STRING, adset_id STRING, adset_name STRING, ad_id STRING, ad_name STRING, spend NUMERIC, impressions INT64, reach INT64, clicks INT64, leads INT64, loaded_at TIMESTAMP) PARTITION BY date`,
].join(';\n') + ';';
return [{ json: { body: { query: sql, useLegacySql: false, location: U, timeoutMs: 60000 } } }];

const j = $input.first().json || {};
if (j.error) throw new Error('BigQuery: ' + (j.error.message || JSON.stringify(j.error)).slice(0, 400));
return [{ json: { ok: true, mensaje: 'Dataset y tablas listos. La tabla leads la crea «Leads a BigQuery» en su primera corrida.' } }];
